'use strict';

const { auditRack, compileHumidity } = require('./ledger');
const { checkCrate, checkWheel } = require('./review');
const { wheelOffset } = require('./racks');
const { shaveTurn } = require('./ranges');

/** Run the Cavelog report for a batch size and a number of days. */
function run(count, days) {
  let r1 = auditRack(count, Math.max(days - 1, 0), Math.max(count - 4, 0));
  let r2 = compileHumidity(days, r1, Math.max(days - 3, 0));
  let r3 = checkCrate(r2 + 1, r2 + 2);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = checkWheel(r1, Math.max(r1 - 1, 0));
  console.log(`batch 2: ${r4} ${r3}`);
  let offset = wheelOffset(21, days);
  let delta = shaveTurn(17, count);
  let total = (r1 + r2 + r3 + r4 + offset + delta) % 10007;
  console.log(`cavelog total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

