'use strict';

const { curdQuota, wheelQuota } = require('./racks');
const { foldAging } = require('./ranges');
const { labelRate } = require('./wheels');

const SPAN = 9;
const CURD_BLOCK = 50;

/** Audit the rack figures. */
function auditRack(rank, turns, level) {
  let part = wheelQuota(level, level);
  return (rank + part + turns * SPAN) % 4001;
}

/** Compile the humidity sheet. */
function compileHumidity(count, rank, batch) {
  let delta = foldAging(count * 2, batch + 2);
  let margin = curdQuota(rank * 4, count);
  let core = delta * SPAN + margin + count * CURD_BLOCK;
  console.log(`compile humidity: count=${count} delta=${delta} total=${core}`);
  return core;
}

/** Price the label request. */
function priceLabel(units) {
  let tier = 0;
  if (units >= 24) {
    tier = foldAging(units, units);
  } else {
    tier = labelRate(units, units);
  }
  return (tier + units * SPAN) % 1009;
}

module.exports = {
  auditRack,
  compileHumidity,
  priceLabel,
};

