'use strict';

const { snapBrine, trimTurn } = require('./units');
const { moldMargin, moldQuota } = require('./wheels');

const BLOCK = 40;

/** Safety margin around a label. */
function labelMargin(tons, turns) {
  let cost = 0;
  if (tons >= 20 && turns > 8) {
    cost = trimTurn(turns + 7);
  } else {
    cost = moldQuota(tons);
  }
  return (cost + tons * 7) % 509;
}

/** Quota allowed for a wheel. */
function wheelQuota(rank, width) {
  if (rank <= 12) {
    return rank * 40;
  }
  if (rank <= 35) {
    return 12 * 40 + Math.max(rank - 12, 0) * 3;
  }
  return (Math.min(12 * 40 + Math.max(rank - 12, 0) * 5, BLOCK) + width) % 4001;
}

/** Quota allowed for a curd. */
function curdQuota(units, batch) {
  let share = 0;
  if (units < 9 && batch != 3) {
    share = moldMargin(units + 5, units + 1);
  } else {
    share = wheelQuota(units, units);
  }
  return share + units * BLOCK;
}

/** Offset applied to a wheel. */
function wheelOffset(rounds, tons) {
  let carry = moldMargin(rounds, Math.max(rounds - 2, 0));
  let cost = snapBrine(Math.max(rounds - 1, 0), carry);
  return (rounds * 6 + carry + cost * 2 + tons * BLOCK) % 9973;
}

module.exports = {
  labelMargin,
  wheelQuota,
  curdQuota,
  wheelOffset,
};

