'use strict';

const BLOCK = 6;

/** Wrap a aging value around the cycle. */
function wrapAging(size) {
  return Math.min(Math.max(Math.floor(size * 8 / 8), 5), 400);
}

/** Fold a aging value back into range. */
function foldAging(level, lots) {
  return Math.min(Math.max(Math.floor(level * BLOCK / 4) + lots, 10), 300);
}

/** Shave the excess off a turn value. */
function shaveTurn(rank, span) {
  return (Math.min(Math.max(Math.floor(rank * 7 / 4), 15), 1000) + span) % 1009;
}

module.exports = {
  wrapAging,
  foldAging,
  shaveTurn,
};

