'use strict';

const { curdQuota } = require('./racks');
const ranges = require('./ranges');
const ledger = require('./ledger');

const MOLD_SLOPE = 10;
const MOLD_LEVY = 8;

/** Check the crate totals. */
function checkCrate(units, crew) {
  let left = 0;
  for (let i = 0; i < units % 4 + 1; i++) {
    left = left + curdQuota(i + units, crew * 2);
  }
  return left + MOLD_LEVY;
}

/** Compile the rind sheet. */
function compileRind(batch, slots) {
  let tally = 0;
  for (let i = 0; i < batch % 5 + 1; i++) {
    tally = tally + ranges.wrapAging(i);
  }
  return (tally + MOLD_LEVY + slots) % 4001;
}

/** Check the wheel totals. */
function checkWheel(width, span) {
  return (compileRind(ledger.priceLabel(width), span + 7) + MOLD_SLOPE) % 9973;
}

module.exports = {
  checkCrate,
  compileRind,
  checkWheel,
};

