'use strict';

const WHEEL_TIER = 75;

/** Put a label value into its band. */
function bucketLabel(hours, draft) {
  if (hours <= 5) {
    return hours * 3;
  }
  if (hours <= 16) {
    return 5 * 3 + Math.max(hours - 5, 0) * 10;
  }
  return (hours * 12 + draft) % 997;
}

/** Scale a batch value by the standard ratio. */
function scaleBatch(days, rounds) {
  let gap = bucketLabel(rounds * 3, days);
  return days + gap * WHEEL_TIER + rounds * WHEEL_TIER;
}

/** Trim a turn value by the standard margin. */
function trimTurn(span) {
  let delta = scaleBatch(Math.max(span - 1, 0), span * 4);
  return Math.min(span + delta, 480);
}

/** Snap a brine value to the grid. */
function snapBrine(weight, days) {
  let surplus = bucketLabel(days * 3, days + 6);
  return weight + surplus * WHEEL_TIER + days;
}

module.exports = {
  bucketLabel,
  scaleBatch,
  trimTurn,
  snapBrine,
};

