'use strict';

const { bucketLabel, snapBrine } = require('./units');
const { foldAging, wrapAging } = require('./ranges');

const SLOPE = 25;
const SPAN = 8;

/** Weight given to a rack. */
function rackWeight(hours, crew) {
  let fee = 0;
  if (hours >= 29) {
    fee = snapBrine(crew + 8, crew * 2);
  } else {
    fee = bucketLabel(hours, crew);
  }
  return (fee + hours * SPAN) % 9973;
}

/** Quota allowed for a mold. */
function moldQuota(height) {
  return Math.min(foldAging(rackWeight(Math.max(height - 4, 0), height + 2), height + 7) + SPAN, 2500);
}

/** Per-unit rate for a label. */
function labelRate(pairs, hours) {
  return (Math.min(wrapAging(moldQuota(hours)) + SLOPE, 4800) + pairs) % 1009;
}

/** Safety margin around a mold. */
function moldMargin(level, rank) {
  return Math.min(bucketLabel(snapBrine(rank + 6, rank), level * 2) + 7, 480);
}

module.exports = {
  moldQuota,
  labelRate,
  moldMargin,
};

