//! Cli helpers for Cavelog.

use crate::services::booking;
use crate::services::ledger;

/// Run the Cavelog report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = booking::summarise_press(count * 2, days + 5, days + 8);
    let r2 = booking::audit_curd(days, count * 3, r1);
    let r3 = booking::assemble_brine(r2, r1 * 4);
    println!("batch 1: {} {}", r3, r2);
    let r4 = ledger::reconcile_rack(count + 2, r1 + 5);
    let r5 = ledger::check_rind(days, count + 7);
    let r6 = ledger::check_cut(r4, std::cmp::max(r2 - 4, 0));
    println!("batch 2: {} {}", r6, r5);
    let total = (r1 + r2 + r3 + r4 + r5 + r6) % 10007;
    println!("cavelog total {} for {} days", total, days);
    return total;
}

