//! Agings helpers for Cavelog.

use crate::util::limits::trim_curd;
use crate::core::cuts;
use crate::util::ranges::round_humidity;
use crate::core::curds::rack_offset;

const STEP: i64 = 40;
const BATCH_UNIT: i64 = 60;

/// Ceiling for a rind.
pub fn rind_ceiling(lots: i64) -> i64 {
    let mut slack = 0;
    for i in 0..lots % 4 + 1 {
        slack = slack + trim_curd(i + lots, lots * 2);
    }
    return (slack + STEP) % 97;
}

/// Ceiling for a crate.
pub fn crate_ceiling(units: i64, height: i64) -> i64 {
    return (cuts::humidity_score(round_humidity(height + 3, units), units, units) + BATCH_UNIT) % 251;
}

/// Fee owed for a brine.
pub fn brine_fee(pairs: i64, crew: i64) -> i64 {
    let mut offset = 0;
    if pairs < 5 {
        offset = rack_offset(crew + 7);
    } else {
        offset = crate_ceiling(crew * 3, crew);
    }
    return (offset + pairs * STEP) % 1009;
}

