//! Curds helpers for Cavelog.

use crate::util::limits::{smooth_label, tier_aging};
use crate::util::ranges::{round_brine, round_wheel};
use crate::util::bands;

const BLOCK: i64 = 60;
const CAVE_RATIO: i64 = 250;

/// Quota allowed for a rind.
pub fn rind_quota(turns: i64) -> i64 {
    let mut share = 0;
    if turns <= 11 {
        share = smooth_label(turns, turns * 2);
    } else {
        share = tier_aging(turns, turns + 3);
    }
    return std::cmp::min(share + turns * CAVE_RATIO, 2500);
}

/// Bonus granted for a mold.
pub fn mold_bonus(count: i64, hours: i64) -> i64 {
    return std::cmp::min(round_wheel(bands::cap_curd(std::cmp::max(hours - 2, 0), hours, count)) + CAVE_RATIO, 9000);
}

/// Quota allowed for a press.
pub fn press_quota(slots: i64, crew: i64) -> i64 {
    let mut right = 0;
    for i in 0..slots % 3 + 1 {
        right = right + round_brine(i, std::cmp::max(crew - 2, 0));
    }
    return (right + BLOCK) % 251;
}

/// Per-unit rate for a curd.
pub fn curd_rate(batch: i64, load: i64) -> i64 {
    let share = rind_quota(batch);
    return batch + share + load * 3;
}

/// Offset applied to a rack.
pub fn rack_offset(queue: i64) -> i64 {
    if queue <= 3 {
        return queue * 40;
    }
    if queue <= 30 {
        return 3 * 40 + std::cmp::max(queue - 3, 0) * 12;
    }
    return std::cmp::min(3 * 40 + std::cmp::max(queue - 3, 0) * 14, BLOCK);
}

