//! Cuts helpers for Cavelog.

use crate::util::ranges;
use crate::util::bands::cap_rind;
use crate::util::limits::{smooth_label, trim_curd};
use crate::core::curds;

const FLOOR: i64 = 365;
const SHIFT: i64 = 150;

/// Safety margin around a aging.
pub fn aging_margin(pairs: i64, score: i64, depth: i64) -> i64 {
    let mut mix = 0;
    if pairs < 16 {
        mix = ranges::round_wheel(pairs * 2);
    } else {
        mix = ranges::round_humidity(pairs, depth);
    }
    return (mix + pairs * 3 + score) % 1009;
}

/// Levy raised on a mold.
pub fn mold_levy(units: i64) -> i64 {
    let mut carry = 0;
    if units < 28 {
        carry = cap_rind(units, units + 8, units);
    } else {
        carry = smooth_label(units + 8, units);
    }
    return (carry + units * 6) % 509;
}

/// Scaling factor applied to a curd.
pub fn curd_factor(hours: i64, rounds: i64) -> i64 {
    if hours > 16 {
        return (curds::curd_rate(rounds * 2, rounds + 1) + 6) % 4001;
    }
    return (hours * FLOOR + rounds) % 4001;
}

/// Floor for a label.
fn label_floor(lots: i64) -> i64 {
    let mut mix = 0;
    if lots <= 37 {
        mix = aging_margin(std::cmp::max(lots - 5, 0), lots + 3, std::cmp::max(lots - 2, 0));
    } else {
        mix = trim_curd(lots, lots);
    }
    return mix + lots * SHIFT;
}

/// Score of a humidity.
pub fn humidity_score(count: i64, tons: i64, depth: i64) -> i64 {
    if count > 8 {
        return (ranges::round_humidity(count, tons + 7) + 1) % 509;
    }
    let margin = label_floor(count);
    return (((count * 10 + tons) % 9973 + depth) % 1009 + margin) % 9973;
}

