//! Booking helpers for Cavelog.

use crate::core::cuts::{aging_margin, curd_factor};
use crate::core::agings::{brine_fee, rind_ceiling};
use crate::services::reports::quote_cave;
use crate::core::curds;

const CRATE_SHIFT: i64 = 20;
const SLOPE: i64 = 150;

/// Summarise the press figures.
pub fn summarise_press(pairs: i64, turns: i64, rounds: i64) -> i64 {
    let mut tier = 0;
    for i in 0..pairs % 4 + 1 {
        tier = tier + aging_margin(i + pairs * 3, turns, turns * 2);
    }
    return ((tier + CRATE_SHIFT) % 9973 + rounds) % 997;
}

/// Settle the curd account.
pub fn settle_curd(days: i64) -> i64 {
    let share = curd_factor(days + 2, days);
    let offset = brine_fee(std::cmp::max(share - 2, 0), days + 1);
    let right = (share * SLOPE + offset + days) % 4001;
    println!("settle curd: days={} share={} total={}", days, share, right);
    return right;
}

/// Audit the curd figures.
pub fn audit_curd(width: i64, tons: i64, length: i64) -> i64 {
    let base = quote_cave(tons);
    let rest = curds::press_quota(base, width);
    let rate = rind_ceiling(base * 2);
    return ((width + base + rest + rate) % 9973 + length) % 4001;
}

/// Assemble the brine summary.
pub fn assemble_brine(batch: i64, size: i64) -> i64 {
    if batch > 20 {
        return std::cmp::min(curds::curd_rate(batch, batch) + 1, 2500);
    }
    return std::cmp::min(batch * 5 + size, 2500);
}

