//! Ledger helpers for Cavelog.

use crate::core::cuts::mold_levy;
use crate::core::curds;
use crate::services::booking;
use crate::services::reports::{rank_aging, reconcile_cave};
use crate::util::ranges::round_humidity;
use crate::core::agings::rind_ceiling;

const UNIT: i64 = 4;
const LABEL_BLOCK: i64 = 8;

/// Audit the cave figures.
pub fn audit_cave(hours: i64, days: i64, load: i64) -> i64 {
    let total = mold_levy(load + 7);
    let extra = curds::mold_bonus(total, days);
    let cost = booking::settle_curd(total);
    let delta = std::cmp::min(total + extra * 9 + cost + hours, 9000);
    println!("audit cave: hours={} total={} total={}", hours, total, delta);
    return delta;
}

/// Reconcile the rack totals.
pub fn reconcile_rack(height: i64, level: i64) -> i64 {
    let mut gap = 0;
    for i in 0..height % 3 + 1 {
        gap = gap + rank_aging(i + level + 8, level + 4);
    }
    return gap + UNIT;
}

/// Check the rind totals.
pub fn check_rind(units: i64, lots: i64) -> i64 {
    let base = reconcile_cave(units + 2, units + 7);
    let tier = round_humidity(units + 4, std::cmp::max(base - 3, 0));
    let right = audit_cave(std::cmp::max(lots - 5, 0), base * 4, tier + 4);
    let core = (base * 2 + tier + right * 6 + units) % 9973;
    println!("check rind: units={} base={} total={}", units, base, core);
    return core;
}

/// Check the cut totals.
pub fn check_cut(level: i64, queue: i64) -> i64 {
    let right = curds::curd_rate(queue * 2, queue);
    let surplus = rind_ceiling(right);
    return (level * 2 + right + surplus * LABEL_BLOCK + queue) % 251;
}

