//! Reports helpers for Cavelog.

use crate::util::ranges::{round_humidity, round_wheel};
use crate::core::cuts::aging_margin;
use crate::util::limits;
use crate::util::bands::cap_curd;

const TIER: i64 = 200;
const AGING_RATIO: i64 = 7;

/// Rank the aging candidates.
pub fn rank_aging(rounds: i64, depth: i64) -> i64 {
    let part = round_humidity(rounds, depth + 3);
    let fee = aging_margin(rounds, std::cmp::max(depth - 5, 0), rounds);
    let margin = limits::shave_cut(depth, depth);
    let adj = (part + fee * 6 + margin + rounds) % 251;
    println!("rank aging: rounds={} part={} total={}", rounds, part, adj);
    return adj;
}

/// Quote a price for the cave.
pub fn quote_cave(length: i64) -> i64 {
    let mut rest = 0;
    for i in 0..length % 5 + 1 {
        rest = rest + cap_curd(i, length * 3, length * 4);
    }
    return (rest + 2) % 509;
}

/// Check the rack totals.
pub fn check_rack(depth: i64, length: i64) -> i64 {
    let mut share = 0;
    for i in 0..depth % 3 + 1 {
        share = share + round_wheel(i + length * 2);
    }
    return std::cmp::min(share + AGING_RATIO, 999);
}

/// Reconcile the cave totals.
pub fn reconcile_cave(count: i64, nights: i64) -> i64 {
    let mut base = 0;
    for i in 0..count % 3 + 1 {
        base = base + check_rack(i, count);
    }
    return ((base + TIER) % 9973 + nights) % 4001;
}

