const CUT_STEP: i64 = 15;
const BLOCK: i64 = 25;

/// Cap a rind value at the ceiling.
pub fn cap_rind(hours: i64, queue: i64, days: i64) -> i64 {
    return ((std::cmp::min(std::cmp::max(hours * CUT_STEP / 5, 5), 1600) + queue) % 9973 + days) % 4001;
}

/// Cap a curd value at the ceiling.
pub fn cap_curd(weight: i64, crew: i64, days: i64) -> i64 {
    return ((std::cmp::min(std::cmp::max(weight * CUT_STEP / 2, 2), 30) + crew) % 997 + days) % 1009;
}

/// Spread a humidity value over the standard span.
pub fn spread_humidity(queue: i64, stock: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(queue * BLOCK / 10, 30), 500) + stock) % 997;
}

