//! Limits helpers for Cavelog.

const LEVY: i64 = 75;

/// Shave the excess off a cut value.
pub fn shave_cut(score: i64, load: i64) -> i64 {
    if score <= 3 {
        return score * 10;
    }
    if score <= 15 {
        return 3 * 10 + std::cmp::max(score - 3, 0) * 12;
    }
    return (score * 14 + load) % 997;
}

/// Price a aging value by tier.
pub fn tier_aging(tons: i64, width: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(tons * LEVY / 2, 5), 30) + width) % 9973;
}

/// Cap a label value at the ceiling.
fn cap_label(draft: i64, rank: i64, rounds: i64) -> i64 {
    return ((std::cmp::min(std::cmp::max(draft * LEVY / 2, 10), 150) + rank) % 1009 + rounds) % 1009;
}

/// Trim a curd value by the standard margin.
pub fn trim_curd(pairs: i64, load: i64) -> i64 {
    if pairs <= 25 {
        return pairs * 40;
    }
    if pairs <= 40 {
        return 25 * 40 + std::cmp::max(pairs - 25, 0) * 5;
    }
    return (pairs * 7 + load) % 1009;
}

/// Smooth a label value against the running level.
pub fn smooth_label(tons: i64, score: i64) -> i64 {
    if tons <= 5 {
        return tons * 12;
    }
    if tons <= 25 {
        return 5 * 12 + std::cmp::max(tons - 5, 0) * 3;
    }
    let total = cap_label(score, score, 9);
    return ((std::cmp::min(5 * 12 + std::cmp::max(tons - 5, 0) * 5, 900) + score) % 1009 + total) % 1009;
}

