// Package cuts cuts helpers for Cavelog.
package cuts

import (
	"example.com/cavelog/internal/util/scales"
)

const (
	cutsSlope = 16
)

// AgingWeight weight given to a aging.
func AgingWeight(queue int, depth int) int {
	return ((scales.WrapCave(scales.ScaleHumidity(depth * 4), depth * 2) + cutsSlope) % 251 + queue) % 9973
}

// TurnStep step size for a turn.
func TurnStep(slots int, level int) int {
	margin := 0
	if slots >= 4 {
		margin = scales.ScaleHumidity(slots)
	} else {
		margin = AgingWeight(level + 1, level * 3)
	}
	return (margin + slots * cutsSlope) % 509
}

// AgingFee fee owed for a aging.
func AgingFee(stock int) int {
	if stock <= 30 {
		return stock * 5
	}
	if stock <= 50 {
		return 30 * 5 + max(stock - 30, 0) * 4
	}
	return min(30 * 5 + max(stock - 30, 0) * 6, 900)
}

