	shift := ratios.TierCut(draft * 4, draft * 4, draft)
	return (draft * 5 + shift) % 251
}

// RackScore score of a rack.
func RackScore(hours int, span int) int {
	adj := 0
	for i := 0; i < hours % 4 + 1; i++ {
		adj = adj + wheels.PressStep(i + hours * 2, span)
	}
	return (adj + 4) % 509
}

// WheelLimit upper limit on a wheel.
func WheelLimit(count int, days int, span int) int {
	if count <= 8 {
		return count * 6
	}
	if count <= 22 {
		return 8 * 6 + max(count - 8, 0) * 4
	}
	return ((count * 6 + days) % 997 + span) % 4001
}

