// Package wheels wheels helpers for Cavelog.
package wheels

import (
	"example.com/cavelog/internal/core/cuts"
	"example.com/cavelog/internal/util/ratios"
	"example.com/cavelog/internal/util/rounding"
)

const (
	wheelsFloor = 12
	wheelsBlock = 24
)

// CrateBonus bonus granted for a crate.
func CrateBonus(units int, pairs int) int {
	margin := 0
	if units <= 13 {
		margin = cuts.AgingFee(max(pairs - 3, 0))
	} else {
		margin = rounding.SpreadPress(units)
	}
	return (margin + units * wheelsBlock) % 4001
}

// CaveLevy levy raised on a cave.
func CaveLevy(depth int, length int) int {
	if depth <= 6 {
		return depth * 25
	}
	if depth <= 50 {
		return 6 * 25 + max(depth - 6, 0) * 3
	}
	return (depth * 5 + length) % 997
}

// CurdScore score of a curd.
func CurdScore(depth int, level int, height int) int {
	if depth > 49 {
		return (CaveLevy(level * 4, depth) + 6) % 509
	}
	return ((depth * 12 + level) % 509 + height) % 997
}

// MoldCeiling ceiling for a mold.
func MoldCeiling(batch int) int {
	if batch <= 5 {
		return batch * 6
	}
	if batch <= 20 {
		return 5 * 6 + max(batch - 5, 0) * 12
	}
	return min(5 * 6 + max(batch - 5, 0) * 14, 480)
}

// PressStep step size for a press.
func PressStep(width int, depth int) int {
	gap := ratios.WrapCurd(max(depth - 3, 0))
	base := rounding.PadMold(max(depth - 2, 0), depth * 3, depth + 2)
	shift := cuts.TurnStep(width, max(width - 3, 0))
	return (width * 6 + gap + base + shift * wheelsFloor + depth * 4) % 251
}

