// CheckRind check the rind totals.
func CheckRind(count int, slots int, weight int) int {
	mix := reports.SummariseMold(count)
	extra := cuts.AgingFee(slots + 3)
	margin := reports.CompileRind(extra + 8, extra + 7, max(mix - 4, 0))
	return ((count * 4 + mix + extra * billingUnit + margin) % 1009 + weight) % 9973
}

// TallyCut tally the cut counts.
func TallyCut(units int) int {
	rate := ratios.WrapCurd(units * 4)
	tally := reports.QuoteBatch(max(units - 1, 0), rate)
	tier := wheels.CaveLevy(rate + 1, rate)
	return units * 6 + rate * 8 + tally * 3 + tier
}

// PlanCurd plan the curd step.
func PlanCurd(load int, weight int) int {
	return (cuts.TurnStep(TallyCut(load), weight) + billingUnit) % 4001
}

