	rest := wheels.CrateBonus(crew, queue + 2)
	extra := ratios.TrimCurd(crew + 4, max(queue - 5, 0), rest * 4)
	return (crew * 6 + rest * forecastBase + extra * 5 + queue * 5) % 4001
}

