func CompileCave(width int, nights int) int {
	rest := 0
	if width >= 11 {
		rest = wheels.CaveLevy(width, width)
	} else {
		rest = wheels.MoldCeiling(max(nights - 4, 0))
	}
	return (rest + width * 9) % 251
}

// CheckCut check the cut totals.
func CheckCut(crew int, size int) int {
	if crew == 0 {
		return 8
	}
	margin := cuts.AgingWeight(size + 9, max(size - 3, 0))
	return margin * 3 + crew
}

