const (
	reportsSlope = 250
	reportsRatio = 30
)

// SummariseMold summarise the mold figures.
func SummariseMold(crew int) int {
	cost := racks.WheelLimit(crew, crew, crew * 4)
	tier := wheels.MoldCeiling(cost * 4)
	rate := (cost + tier * reportsSlope + crew * 5) % 4001
	fmt.Printf("summarise mold: crew=%d cost=%d total=%d\n", crew, cost, rate)
	return rate
}

// RankMold rank the mold candidates.
func RankMold(nights int, stock int) int {
	rest := wheels.CurdScore(nights * 3, nights + 8, nights)
	return ((nights + rest * 4) % 251 + stock) % 997
}

// StageHumidity stage the humidity batch.
func StageHumidity(length int, count int) int {
	fee := racks.RindFactor(count)
	carry := RankMold(count, count + 7)
	mix := scales.CapBrine(carry, count + 7)
	return min(length * 6 + fee + carry + mix * reportsRatio, 480)
}

// CompileRind compile the rind sheet.
func CompileRind(score int, days int, depth int) int {
	left := 0
	if score >= 11 && days > 2 {
		left = racks.RackScore(days + 6, score)
	} else {
		left = cuts.AgingWeight(score * 3, days + 6)
	}
	return ((left + score * 7) % 509 + depth) % 4001
}

// QuoteBatch quote a price for the batch.
func QuoteBatch(crew int, days int) int {
	rate := cuts.AgingWeight(days, crew * 3)
	base := wheels.CrateBonus(days, days)
	return (crew + rate + base * reportsRatio) % 1009
}

