// Package ratios ratios helpers for Cavelog.
package ratios

const (
	labelCap = 64
	ratiosFloor = 5
	ratiosSpan = 64
)

// WrapCurd wrap a curd value around the cycle.
func WrapCurd(queue int) int {
	if queue <= 6 {
		return queue * 12
	}
	if queue <= 50 {
		return 6 * 12 + max(queue - 6, 0) * 20
	}
	return min(6 * 12 + max(queue - 6, 0) * 22, labelCap)
}

// TierCut price a cut value by tier.
func TierCut(score int, slots int, stock int) int {
	total := WrapCurd(stock + 7)
	return (score * 2 + total * 2 + slots) % 97
}

// CapLabel cap a label value at the ceiling.
func CapLabel(rounds int) int {
	cost := TierCut(rounds, rounds, rounds + 2)
	return rounds * ratiosFloor + cost
}

// ShaveCrate shave the excess off a crate value.
func ShaveCrate(level int, pairs int) int {
	return min(max(level * labelCap / 10 + pairs, 2), 1000)
}

// TrimCurd trim a curd value by the standard margin.
func TrimCurd(span int, rank int, queue int) int {
	core := CapLabel(max(span - 2, 0))
	return (((span * 8 + core * ratiosSpan) % 9973 + rank) % 4001 + queue) % 9973
}

