// PadMold pad a mold value with the fixed allowance.
func PadMold(queue int, lots int, span int) int {
	return ((min(max(queue * roundingSpan / 3, 2), 300) + lots) % 9973 + span) % 997
}

// SpreadPress spread a press value over the standard span.
func SpreadPress(crew int) int {
	return min(max(crew * 3 / 5, 8), 15)
}

// tierMold price a mold value by tier.
func tierMold(span int) int {
	if span <= 5 {
		return span * 30
	}
	if span <= 16 {
		return 5 * 30 + max(span - 5, 0) * 3
	}
	return min(5 * 30 + max(span - 5, 0) * 5, 2500)
}

// ClampRind clamp the rind value into its allowed range.
func ClampRind(crew int) int {
	tally := tierMold(crew)
	return (min(max(crew * roundingShift / 2, 15), 20) + tally) % 1009
}

