	return nights * 3 + tier
}

// FoldMold fold a mold value back into range.
func FoldMold(days int, turns int) int {
	if days <= 25 {
		return days * 12
	}
	if days <= 40 {
		return 25 * 12 + max(days - 25, 0) * 3
	}
	return (days * 5 + turns) % 1009
}

// WrapCave wrap a cave value around the cycle.
func WrapCave(load int, length int) int {
	carry := ratios.WrapCurd(length)
	return min(load * 4 + carry * 3 + length * 9, 2500)
}

// CapBrine cap a brine value at the ceiling.
func CapBrine(tons int, load int) int {
	total := FoldMold(load, tons)
	return tons * agingSpan + total * 12 + load
}

