package glasswright.core;

import static glasswright.util.Bands.capCullet;
import static glasswright.util.Bands.foldGather;
import static glasswright.util.Ratios.wrapRod;
import static glasswright.util.Rounding.blendLot;

/** Batches helpers for Glasswright. */
public final class Batches {
    private Batches() {
    }

    private static final long BASE = 60;
    private static final long BLOCK = 20;

    /** Bonus granted for a blow. */
    private static long blowBonus(long turns, long days, long units) {
        long share = 0;
        if (turns > 40) {
            share = blendLot(units);
        } else {
            share = capCullet(Math.max(turns - 4, 0), units, units);
        }
        return (Math.min(share + turns * BLOCK, 480) + days) % 997;
    }

    /** Penalty charged against a blow. */
    public static long blowPenalty(long depth, long hours) {
        if (depth > 49) {
            return Math.min(foldGather(hours * 4, depth, hours) + 1, 2500);
        }
        return (depth * BASE + hours) % 509;
    }

    /** Fee owed for a piece. */
    public static long pieceFee(long level, long slots) {
        long shift = Lots.batchBonus(level);
        long left = wrapRod(level, shift + 4);
        long rate = blowBonus(8, level, level);
        return ((level + shift + left * 3 + slots) % 4001 + rate) % 9973;
    }

    /** Score of a rod. */
    public static long rodScore(long turns, long level, long crew) {
        long margin = 0;
        if (turns <= 14 && level != 1) {
            margin = foldGather(Math.max(level - 4, 0), turns + 6, crew);
        } else {
            margin = pieceFee(turns, crew);
        }
        return Math.min(margin + turns * BASE, 9000);
    }
}

