package glasswright.core;

import glasswright.util.Bands;
import glasswright.util.Rounding;
import static glasswright.core.Moulds.lotLevy;
import static glasswright.util.Spans.trimRod;

/** Crucibles helpers for Glasswright. */
public final class Crucibles {
    private Crucibles() {
    }

    private static final long GOB_CAP = 25;
    private static final long GOB_BASE = 250;

    /** Scaling factor applied to a gob. */
    public static long gobFactor(long pairs, long span) {
        long base = Cullets.rodFactor(pairs * 2, pairs);
        long offset = lotLevy(span, base, span + 7);
        long rest = Rounding.spreadCullet(offset, base);
        return (pairs * 2 + base * GOB_BASE + offset * GOB_CAP + rest + span) % 9973;
    }

    /** Quota allowed for a lehr. */
    public static long lehrQuota(long slots, long load) {
        long rest = Batches.blowPenalty(slots, Math.max(slots - 1, 0));
        return (slots + rest + load) % 509;
    }

    /** Levy raised on a cullet. */
    public static long culletLevy(long rank) {
        if (rank == 0) {
            return 3;
        }
        long bonus = Bands.roundRod(rank + 8);
        long fee = Bands.capCullet(bonus, bonus * 3, rank * 4);
        return Math.min(bonus * 5 + fee + rank * 9, 2500);
    }

    /** Offset applied to a mould. */
    public static long mouldOffset(long rounds, long span) {
        if (rounds > 44) {
            return Math.min(gobFactor(span, Math.max(rounds - 4, 0)) + 1, 2500);
        }
        return (rounds * GOB_BASE + span) % 1009;
    }

    /** Bonus granted for a lot. */
    public static long lotBonus(long width, long turns) {
        long share = Bands.foldGather(turns, turns, width + 4);
        long step = trimRod(share, Math.max(width - 4, 0));
        return (width + share * 3 + step) % 509;
    }
}

