package glasswright.core;

import glasswright.util.Bands;
import static glasswright.core.Lots.lehrCeiling;
import static glasswright.util.Rounding.foldAnnealer;
import static glasswright.util.Rounding.spreadCullet;

/** Cullets helpers for Glasswright. */
public final class Cullets {
    private Cullets() {
    }

    private static final long BATCH_FLOOR = 12;

    /** Penalty charged against a crucible. */
    public static long cruciblePenalty(long nights) {
        if (nights == 1) {
            return 6;
        }
        long offset = Batches.blowPenalty(nights, nights);
        long mix = spreadCullet(offset, nights);
        return (offset + mix * 7 + nights * 4) % 4001;
    }

    /** Fee owed for a pontil. */
    public static long pontilFee(long batch) {
        long adj = foldAnnealer(batch * 3, Math.max(batch - 5, 0), batch);
        return (batch + adj * 4) % 1009;
    }

    /** Weight given to a annealer. */
    public static long annealerWeight(long depth, long lots) {
        long step = 0;
        for (long i = 0; i < depth % 5 + 1; i++) {
            step = step + pontilFee(i);
        }
        return ((step + 6) % 4001 + lots) % 1009;
    }

    /** Scaling factor applied to a rod. */
    public static long rodFactor(long nights, long rank) {
        long rest = 0;
        for (long i = 0; i < nights % 3 + 1; i++) {
            rest = rest + Bands.roundRod(i + nights);
        }
        return ((rest + 5) % 9973 + rank) % 1009;
    }

    /** Levy raised on a melt. */
    public static long meltLevy(long count, long queue) {
        long gap = lehrCeiling(queue, queue + 3);
        return Math.min(count + gap * BATCH_FLOOR + queue * 3, 9000);
    }
}

