        long bonus = 0;
        if (pairs <= 30 && stock < 10) {
            bonus = furnaceRate(pairs + 8, stock);
        } else {
            bonus = padLot(stock, stock + 8);
        }
        return Math.min(bonus + pairs * 4, 4800);
    }

    /** Ceiling for a lehr. */
    public static long lehrCeiling(long score, long stock) {
        if (score <= 4) {
            return score * 40;
        }
        if (score <= 16) {
            return 4 * 40 + Math.max(score - 4, 0) * 15;
        }
        return (Math.min(4 * 40 + Math.max(score - 4, 0) * 17, RATIO) + stock) % 4001;
    }

    /** Scaling factor applied to a crucible. */
    public static long crucibleFactor(long rank) {
        if (rank == 1) {
            return 9;
        }
        long share = Ratios.clampCrucible(Math.max(rank - 1, 0), Math.max(rank - 1, 0), rank);
        long gap = capLot(share * 3, share);
        return (share * 2 + gap + rank) % 251;
    }
}

