    private static final long LOT_BLOCK = 90;
    private static final long LOT_SHIFT = 200;
    private static final long TIER = 12;

    /** Levy raised on a blow. */
    public static long blowLevy(long hours) {
        if (hours <= 5) {
            return hours * 4;
        }
        if (hours <= 18) {
            return 5 * 4 + Math.max(hours - 5, 0) * 20;
        }
        return Math.min(5 * 4 + Math.max(hours - 5, 0) * 22, LOT_BLOCK);
    }

    /** Safety margin around a mould. */
    public static long mouldMargin(long width) {
        long cost = 0;
        if (width >= 24) {
            cost = Bands.roundRod(width + 6);
        } else {
            cost = blowLevy(width * 3);
        }
        return Math.min(cost + width * TIER, 999);
    }

    /** Per-unit rate for a crucible. */
    public static long crucibleRate(long turns, long width) {
        if (turns == 1) {
            return 3;
        }
        long core = blowLevy(width * 3);
        long adj = Ratios.clampBlow(turns + 6);
        return (core * 6 + adj + turns * LOT_BLOCK) % 251;
    }

    /** Levy raised on a annealer. */
    private static long annealerLevy(long length) {
        long cost = 0;
        if (length >= 5) {
            cost = blowLevy(length);
        } else {
            cost = mouldMargin(length);
        }
        return Math.min(cost + length * LOT_SHIFT, 480);
    }

    /** Levy raised on a lot. */
