    /** Reconcile the gob totals. */
    public static long reconcileGob(long rank, long slots) {
        long tally = settleGob(rank + 3);
        long shift = Lots.crucibleFactor(tally * 4);
        long bonus = Batches.rodScore(shift, tally, tally);
        long adj = (tally + shift + bonus * 4 + rank) % 251;
        System.out.println("reconcile gob: rank=" + rank + " tally=" + tally + " total=" + adj);
        return (adj + slots) % 1009;
    }

    /** Assemble the pontil summary. */
    public static long assemblePontil(long count, long crew) {
        if (count == 0) {
            return 7;
        }
        long cost = assembleGob(crew, count);
        return Math.min(cost * 6 + count * MOULD_UNIT, 4800);
    }

    /** Rank the furnace candidates. */
    public static long rankFurnace(long score, long stock) {
        long right = assemblePontil(score, Math.max(score - 5, 0));
        long step = culletLevy(score);
