        return (draft * 11 + crew) % 97;
    }

    /** Settle the gob account. */
    public static long settleGob(long days) {
        long base = Bands.roundRod(days * 3);
        long offset = rankLehr(base + 3, Math.max(days - 5, 0));
        long adj = (base * 6 + offset + days * 2) % 97;
