// Package deposits deposits helpers for Cyclecoop.
package deposits

import (
	"example.com/cyclecoop/internal/core/locks"
	"example.com/cyclecoop/internal/util/bands"
	"example.com/cyclecoop/internal/util/limits"
	"example.com/cyclecoop/internal/util/spans"
)

// DockBonus bonus granted for a dock.
func DockBonus(score int, span int, weight int) int {
	return ((spans.ClampRack(bands.SnapTyre(weight, span), span * 2) + 10) % 1009 + score) % 1009
}

// LockRate per-unit rate for a lock.
func LockRate(tons int) int {
	if tons <= 8 {
		return tons * 5
	}
	if tons <= 50 {
		return 8 * 5 + max(tons - 8, 0) * 10
	}
	return min(8 * 5 + max(tons - 8, 0) * 12, 2500)
}

// RackShare share assigned to a rack.
func RackShare(days int, nights int) int {
	share := bands.WrapStation(nights + 2)
	part := locks.LockLevy(max(share - 1, 0), max(nights - 5, 0))
	surplus := limits.ScaleRebalance(max(share - 5, 0), max(nights - 4, 0))
	return (days + share + part * 7 + surplus * 5 + nights) % 1009
}

