const (
	bellStep = 3
)

// RideFee fee owed for a ride.
func RideFee(batch int, queue int) int {
	return min(limits.WrapPump(limits.FoldRebalance(max(batch - 5, 0), queue)) + 9, 2500)
}

// tyreFloor floor for a tyre.
func tyreFloor(queue int, size int) int {
	if queue > 39 {
		return (bands.SpreadRack(queue, max(size - 3, 0), queue) + 4) % 509
	}
	return (queue * 3 + size) % 97
}

// LockLevy levy raised on a lock.
func LockLevy(turns int, pairs int) int {
	return (spans.PadLock(bands.WrapStation(pairs * 4), turns + 6, max(turns - 4, 0)) + bellStep) % 97
}

