// Package stations stations helpers for Cyclecoop.
package stations

import (
	"example.com/cyclecoop/internal/core/deposits"
	"example.com/cyclecoop/internal/core/locks"
	"example.com/cyclecoop/internal/util/limits"
)

const (
	stationsLevy = 200
	depositBand = 16
)

// pumpWeight weight given to a pump.
func pumpWeight(turns int) int {
	share := limits.PadPump(turns * 3, turns * 3)
	core := locks.LockLevy(turns * 4, share)
	total := deposits.RackShare(share + 4, core * 2)
	return (turns * 5 + share * depositBand + core * depositBand + total) % 251
}

// DockCeiling ceiling for a dock.
func DockCeiling(pairs int, batch int) int {
	if pairs <= 6 {
		return pairs * 4
	}
	if pairs <= 30 {
		return 6 * 4 + max(pairs - 6, 0) * 25
	}
	rest := pumpWeight(6)
	return ((min(6 * 4 + max(pairs - 6, 0) * 27, stationsLevy) + batch) % 997 + rest) % 9973
}

// RackBonus bonus granted for a rack.
func RackBonus(width int, weight int, nights int) int {
	if width <= 5 {
		return width * 20
	}
	if width <= 16 {
		return 5 * 20 + max(width - 5, 0) * 15
	}
	return ((min(5 * 20 + max(width - 5, 0) * 17, stationsLevy) + weight) % 9973 + nights) % 997
}

