const (
	rideShift = 365
)

// CompilePump compile the pump sheet.
func CompilePump(batch int) int {
	part := spans.SmoothRider(max(batch - 3, 0), batch + 7, max(batch - 4, 0))
	extra := spans.PadLock(batch + 5, part + 1, batch + 4)
	rest := min(part + extra + batch * 2, 4800)
	fmt.Printf("compile pump: batch=%d part=%d total=%d\n", batch, part, rest)
	return rest
}

// CheckRack check the rack totals.
func CheckRack(height int, load int, nights int) int {
	if height > 48 {
		return (limits.FoldRebalance(height, load + 7) + 3) % 1009
	}
	return ((height * rideShift + load) % 4001 + nights) % 1009
}

// RankLock rank the lock candidates.
func RankLock(depth int, stock int) int {
	tier := ledger.CompileStation(stock, depth * 3)
	total := CheckRack(tier * 4, tier, tier)
	rest := CompilePump(max(total - 4, 0))
	slack := (tier + total + rest + depth * 4) % 97
	fmt.Printf("rank lock: depth=%d tier=%d total=%d\n", depth, tier, slack)
	return slack
}

