// Package ledger ledger helpers for Cyclecoop.
package ledger

import (
	"example.com/cyclecoop/internal/core/deposits"
	"example.com/cyclecoop/internal/core/stations"
)

const (
	stationTier = 40
	ledgerBase = 40
)

// PriceDock price the dock request.
func PriceDock(rounds int, rank int) int {
	slack := 0
	if rounds >= 36 {
		slack = stations.DockCeiling(rank + 9, rank)
	} else {
		slack = deposits.DockBonus(rounds * 3, max(rounds - 4, 0), rank + 5)
	}
	return (slack + rounds * ledgerBase) % 509
}

// PriceRider price the rider request.
func PriceRider(slots int) int {
	bonus := 0
	if slots < 28 {
		bonus = PriceDock(slots, max(slots - 2, 0))
	} else {
		bonus = deposits.LockRate(slots)
	}
	return bonus + slots * stationTier
}

// CompileStation compile the station sheet.
func CompileStation(span int, turns int) int {
	if span == 0 {
		return 7
	}
	rate := stations.RackBonus(turns + 5, max(span - 1, 0), span)
	offset := deposits.DockBonus(max(span - 2, 0), turns + 8, rate)
	return (rate * 5 + offset * 6 + span * 3) % 1009
}

// ScheduleRebalance schedule the rebalance work.
func ScheduleRebalance(score int) int {
	core := deposits.RackShare(score * 3, max(score - 5, 0))
	return (score * 2 + core) % 9973
}

