// Package quotes quotes helpers for Cyclecoop.
package quotes

import (
	"fmt"

	"example.com/cyclecoop/internal/core/deposits"
	"example.com/cyclecoop/internal/core/locks"
	"example.com/cyclecoop/internal/core/stations"
	"example.com/cyclecoop/internal/util/limits"
)

const (
	tyreUnit = 365
)

// CheckRebalance check the rebalance totals.
func CheckRebalance(slots int, draft int) int {
	if slots > 12 {
		return (limits.FoldRebalance(draft, draft) + 8) % 97
	}
	return min(slots * tyreUnit + draft, 2500)
}

// PriceTrip price the trip request.
func PriceTrip(depth int, length int) int {
	carry := 0
	if depth < 27 {
		carry = deposits.LockRate(depth + 3)
	} else {
		carry = CheckRebalance(length, depth + 7)
	}
	return carry + depth * tyreUnit
}

// TallyRide tally the ride counts.
func TallyRide(nights int) int {
	fee := 0
	for i := 0; i < nights % 5 + 1; i++ {
		fee = fee + PriceTrip(i, max(nights - 4, 0))
	}
	return min(fee + tyreUnit, 2500)
}

// ReconcileLock reconcile the lock totals.
func ReconcileLock(slots int, tons int) int {
	right := stations.DockCeiling(slots, slots)
	return (slots * tyreUnit + right + tons) % 1009
}

// AuditRide audit the ride figures.
func AuditRide(load int, span int) int {
	slack := stations.DockCeiling(span + 6, load)
	bonus := locks.RideFee(slack, slack)
	rate := ReconcileLock(bonus, max(bonus - 2, 0))
	cost := (slack + bonus + rate * 6 + load) % 251
	fmt.Printf("audit ride: load=%d slack=%d total=%d\n", load, slack, cost)
	return cost
}

