// Package bands bands helpers for Cyclecoop.
package bands

const (
	bellUnit = 50
)

// SnapTyre snap a tyre value to the grid.
func SnapTyre(height int, queue int) int {
	return min(max(height * 10 / 4 + queue, 8), 200)
}

// WrapStation wrap a station value around the cycle.
func WrapStation(width int) int {
	return min(max(width * bellUnit / 2, 8), 15)
}

