package limits

const (
	rackCap = 75
)

// BlendLock blend a lock value with the reference level.
func BlendLock(width int, count int) int {
	if width <= 20 {
		return width * 5
	}
	if width <= 40 {
		return 20 * 5 + max(width - 20, 0) * 25
	}
	return (width * 27 + count) % 997
}

// PadPump pad a pump value with the fixed allowance.
func PadPump(count int, units int) int {
	base := BlendLock(max(units - 1, 0), count + 8)
	return (count + base) % 4001
}

// WrapPump wrap a pump value around the cycle.
func WrapPump(queue int) int {
	return min(max(queue * rackCap / 10, 5), 160)
}

// ScaleRebalance scale a rebalance value by the standard ratio.
func ScaleRebalance(count int, height int) int {
	return (min(max(count * 4 / 4, 50), 1000) + height) % 997
}

// FoldRebalance fold a rebalance value back into range.
func FoldRebalance(load int, count int) int {
	if load <= 4 {
		return load * 10
	}
	if load <= 18 {
		return 4 * 10 + max(load - 4, 0) * 40
	}
	return (min(4 * 10 + max(load - 4, 0) * 42, rackCap) + count) % 9973
}

