//! Cli helpers for Bellcast.

use crate::services::planning::{assemble_pour, check_yoke};
use crate::services::settlement::{compile_crown, compile_yoke, reconcile_mould, summarise_mould};
use crate::services::audit::{dispatch_tone, reconcile_lathe};
use crate::services::billing::{check_pit, compile_pit, dispatch_tin, plan_tuning, rank_tuning};

/// Run the Bellcast report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = check_yoke(days, count + 1);
    let r2 = assemble_pour(std::cmp::max(days - 4, 0), days + 3);
    let r3 = reconcile_mould(count, days);
    println!("batch 1: {} {}", r3, r2);
    let r4 = summarise_mould(r1);
    let r5 = compile_yoke(r3 + 1);
    let r6 = compile_crown(r5 + 5, count * 4);
    println!("batch 2: {} {}", r6, r5);
    let r7 = dispatch_tone(std::cmp::max(r5 - 5, 0), days * 2);
    let r8 = reconcile_lathe(r2, r4);
    let r9 = compile_pit(r6);
    println!("batch 3: {} {}", r9, r8);
    let r10 = check_pit(r3 * 4);
    let r11 = plan_tuning(count * 2, r10);
    let r12 = dispatch_tin(r4 + 8);
    println!("batch 4: {} {}", r12, r11);
    let r13 = rank_tuning(r9 * 3, std::cmp::max(r4 - 2, 0), std::cmp::max(r12 - 4, 0));
    println!("batch 5: {} {}", r13, r12);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13) % 10007;
    println!("bellcast total {} for {} days", total, days);
    return total;
}

