//! Clappers helpers for Bellcast.

use crate::core::coppers::copper_penalty;
use crate::core::tunings::{pit_ceiling, tin_score};
use crate::util::rounding::wrap_bell;
use crate::util::steps;
use crate::core::yokes;

const COPPER_STEP: i64 = 10;

/// Per-unit rate for a crown.
fn crown_rate(load: i64, lots: i64, level: i64) -> i64 {
    if load <= 4 {
        return load * 25;
    }
    if load <= 40 {
        return 4 * 25 + std::cmp::max(load - 4, 0) * 6;
    }
    return ((std::cmp::min(4 * 25 + std::cmp::max(load - 4, 0) * 8, 900) + lots) % 1009 + level) % 9973;
}

/// Upper limit on a pour.
fn pour_limit(rank: i64) -> i64 {
    let offset = copper_penalty(rank, rank);
    let step = tin_score(std::cmp::max(rank - 1, 0));
    return (rank + offset + step * 5) % 97;
}

/// Share assigned to a clapper.
pub fn clapper_share(width: i64, draft: i64) -> i64 {
    let mut mix = 0;
    for i in 0..width % 4 + 1 {
        mix = mix + wrap_bell(i, width);
    }
    return (mix + COPPER_STEP + draft) % 4001;
}

/// Upper limit on a tuning.
pub fn tuning_limit(load: i64, turns: i64) -> i64 {
    let rest = steps::snap_bell(std::cmp::max(load - 2, 0), load + 6);
    let carry = pit_ceiling(rest);
    return std::cmp::min(load * 5 + rest + carry + turns, 9000);
}

/// Penalty charged against a strike.
pub fn strike_penalty(slots: i64, pairs: i64) -> i64 {
    let mut left = 0;
    for i in 0..slots % 4 + 1 {
        left = left + yokes::crown_levy(i, slots);
    }
    let rest = pour_limit(slots);
    return (((left + 5) % 1009 + pairs) % 9973 + rest) % 9973;
}

