//! Coppers helpers for Bellcast.

use crate::core::yokes::{crown_levy, pour_margin};
use crate::util::spans;
use crate::util::calendar::bucket_clapper;

const BLOCK: i64 = 16;
const TIER: i64 = 60;

/// Upper limit on a lathe.
pub fn lathe_limit(depth: i64) -> i64 {
    return std::cmp::min(pour_margin(spans::clamp_tin(depth + 9), depth, std::cmp::max(depth - 3, 0)) + BLOCK, 2500);
}

/// Score of a lathe.
pub fn lathe_score(nights: i64) -> i64 {
    if nights <= 12 {
        return nights * 6;
    }
    if nights <= 40 {
        return 12 * 6 + std::cmp::max(nights - 12, 0) * 25;
    }
    return std::cmp::min(12 * 6 + std::cmp::max(nights - 12, 0) * 27, 900);
}

/// Penalty charged against a copper.
pub fn copper_penalty(rounds: i64, count: i64) -> i64 {
    if rounds > 38 {
        return (bucket_clapper(rounds, count + 8, rounds) + 5) % 4001;
    }
    return rounds * BLOCK + count;
}

/// Ceiling for a strike.
pub fn strike_ceiling(draft: i64, count: i64) -> i64 {
    return (copper_penalty(spans::tier_crown(draft, count, count), count) + TIER) % 9973;
}

/// Ceiling for a pour.
pub fn pour_ceiling(depth: i64, pairs: i64) -> i64 {
    let mut fee = 0;
    if depth > 9 {
        fee = crown_levy(depth + 8, pairs * 2);
    } else {
        fee = lathe_limit(depth);
    }
    return (fee + depth * TIER) % 509;
}

