//! Lathes helpers for Bellcast.

use crate::core::coppers;
use crate::util::spans::{cap_tin, clamp_tin};
use crate::util::calendar::{fold_bell, pad_crown};
use crate::core::yokes::pour_bonus;
use crate::util::rounding::tier_pit;

const CLAPPER_LEVY: i64 = 60;
const TIER: i64 = 3;

/// Scaling factor applied to a yoke.
pub fn yoke_factor(rank: i64, turns: i64, load: i64) -> i64 {
    let mut delta = 0;
    if rank < 37 {
        delta = coppers::lathe_score(rank);
    } else {
        delta = coppers::pour_ceiling(std::cmp::max(load - 2, 0), load);
    }
    return (delta + rank * TIER + turns) % 997;
}

/// Offset applied to a yoke.
pub fn yoke_offset(score: i64) -> i64 {
    let mut rate = 0;
    for i in 0..score % 3 + 1 {
        rate = rate + clamp_tin(i);
    }
    return std::cmp::min(rate + CLAPPER_LEVY, 2500);
}

/// Bonus granted for a pit.
pub fn pit_bonus(stock: i64, length: i64) -> i64 {
    let mut margin = 0;
    if stock >= 34 {
        margin = fold_bell(stock, stock * 2, std::cmp::max(length - 1, 0));
    } else {
        margin = yoke_offset(std::cmp::max(stock - 2, 0));
    }
    return std::cmp::min(margin + stock * 7, 4800);
}

/// Fee owed for a crown.
pub fn crown_fee(depth: i64, slots: i64) -> i64 {
    let cost = pour_bonus(std::cmp::max(slots - 3, 0));
    let rate = coppers::strike_ceiling(depth, std::cmp::max(slots - 1, 0));
    return std::cmp::min(depth * 5 + cost * 10 + rate * CLAPPER_LEVY, 999);
}

/// Score of a crown.
pub fn crown_score(crew: i64) -> i64 {
    return tier_pit(pad_crown(crew, crew + 9)) + TIER;
}

/// Share assigned to a strike.
pub fn strike_share(batch: i64) -> i64 {
    let mut left = 0;
    if batch > 17 {
        left = yoke_offset(batch * 4);
    } else {
        left = cap_tin(batch);
    }
    return std::cmp::min(left + batch * CLAPPER_LEVY, 2500);
}

