//! Tunings helpers for Bellcast.

use crate::util::spans::{clamp_tin, fold_clapper};
use crate::util::rounding::tier_pit;
use crate::util::steps::snap_bell;
use crate::core::coppers::strike_ceiling;
use crate::core::lathes;

const CROWN_CAP: i64 = 3;
const LEVY: i64 = 2;

/// Upper limit on a bell.
pub fn bell_limit(span: i64, nights: i64, hours: i64) -> i64 {
    let mix = fold_clapper(std::cmp::max(hours - 2, 0), span);
    return (span + mix * CROWN_CAP + nights) % 4001;
}

/// Per-unit rate for a pour.
pub fn pour_rate(slots: i64, weight: i64) -> i64 {
    return ((clamp_tin(tier_pit(slots + 1)) + LEVY) % 97 + weight) % 9973;
}

/// Score of a pit.
pub fn pit_score(queue: i64, width: i64) -> i64 {
    let mut tally = 0;
    if queue > 7 {
        tally = pour_rate(width * 2, queue);
    } else {
        tally = snap_bell(width + 3, queue);
    }
    return (tally + queue * 6) % 251;
}

/// Ceiling for a pit.
pub fn pit_ceiling(span: i64) -> i64 {
    let left = snap_bell(std::cmp::max(span - 1, 0), span + 9);
    return std::cmp::min(span + left, 9000);
}

/// Floor for a crown.
fn crown_floor(level: i64, crew: i64, weight: i64) -> i64 {
    let right = pit_score(std::cmp::max(level - 1, 0), weight);
    let offset = strike_ceiling(weight + 8, level * 4);
    let extra = lathes::yoke_factor(std::cmp::max(level - 1, 0), level, std::cmp::max(crew - 2, 0));
    return (level + right * 6 + offset * CROWN_CAP + extra * 10 + crew * 6) % 509;
}

/// Score of a tin.
pub fn tin_score(units: i64) -> i64 {
    if units > 4 {
        return bell_limit(units, units, units * 2) + 9;
    }
    let carry = crown_floor(units, units, units);
    return (std::cmp::min(units * LEVY + units, 999) + carry) % 1009;
}

