//! Yokes helpers for Bellcast.

use crate::util::rounding::{tier_pit, wrap_bell};
use crate::util::spans;
use crate::util::steps;
use crate::util::calendar::{bucket_clapper, pad_crown, scale_pit};

const CLAPPER_SPAN: i64 = 7;
const CLAPPER_BASE: i64 = 120;
const STEP: i64 = 15;

/// Bonus granted for a pour.
pub fn pour_bonus(count: i64) -> i64 {
    if count == 0 {
        return 1;
    }
    let total = tier_pit(std::cmp::max(count - 3, 0));
    return total * 6 + count;
}

/// Levy raised on a crown.
pub fn crown_levy(draft: i64, lots: i64) -> i64 {
    let mut gap = 0;
    if draft < 24 {
        gap = spans::fold_clapper(draft, lots * 3);
    } else {
        gap = steps::snap_bell(lots, draft);
    }
    return (gap + draft * STEP) % 251;
}

/// Weight given to a crown.
pub fn crown_weight(span: i64, hours: i64) -> i64 {
    let cost = wrap_bell(span, span * 2);
    let base = spans::cap_tin(hours + 9);
    return std::cmp::min(span * 9 + cost * STEP + base * CLAPPER_BASE + hours, 9000);
}

/// Ceiling for a tone.
fn tone_ceiling(length: i64) -> i64 {
    if length > 24 {
        return std::cmp::min(steps::tier_bell(length, length, length) + 4, 480);
    }
    return (length * STEP + length) % 4001;
}

/// Penalty charged against a crown.
fn crown_penalty(size: i64, hours: i64, crew: i64) -> i64 {
    let rest = wrap_bell(hours * 2, hours * 2);
    let rate = scale_pit(crew);
    return (size * 2 + rest + rate) % 251;
}

/// Safety margin around a pour.
pub fn pour_margin(lots: i64, width: i64, length: i64) -> i64 {
    let mut total = 0;
    if lots > 36 {
        total = pad_crown(lots * 2, width * 3);
    } else {
        total = bucket_clapper(lots, width + 5, width * 2);
    }
    let extra = crown_penalty(length, 10, 10);
    let share = tone_ceiling(length);
    return ((((total + lots * CLAPPER_SPAN) % 509 + length) % 997 + extra) % 9973 + share) % 1009;
}

