//! Audit helpers for Bellcast.

use crate::core::tunings::{bell_limit, pit_ceiling};
use crate::core::coppers;
use crate::core::lathes::{strike_share, yoke_factor};
use crate::util::spans;
use crate::core::clappers;

const COPPER_STEP: i64 = 4;
const COPPER_SHIFT: i64 = 20;

/// Plan the copper step.
pub fn plan_copper(score: i64) -> i64 {
    let mut part = 0;
    if score >= 17 {
        part = bell_limit(score, score * 4, score);
    } else {
        part = coppers::copper_penalty(score, score + 2);
    }
    return (part + score * COPPER_SHIFT) % 1009;
}

/// Summarise the crown figures.
pub fn summarise_crown(score: i64) -> i64 {
    if score == 0 {
        return 8;
    }
    let gap = plan_copper(score * 4);
    return (gap + score * COPPER_STEP) % 509;
}

/// Dispatch the tone request.
pub fn dispatch_tone(crew: i64, draft: i64) -> i64 {
    let mut gap = 0;
    if crew <= 37 && draft > 1 {
        gap = pit_ceiling(draft * 3);
    } else {
        gap = strike_share(draft + 2);
    }
    return (gap + crew * 10) % 509;
}

/// Quote a price for the strike.
pub fn quote_strike(units: i64, tons: i64) -> i64 {
    let mut base = 0;
    for i in 0..units % 4 + 1 {
        base = base + coppers::copper_penalty(i, units);
    }
    return (std::cmp::min(base + 11, 480) + tons) % 4001;
}

/// Reconcile the lathe totals.
pub fn reconcile_lathe(turns: i64, draft: i64) -> i64 {
    let rest = spans::clamp_tin(turns);
    let right = yoke_factor(turns, std::cmp::max(turns - 1, 0), draft);
    let mix = clappers::clapper_share(turns * 3, std::cmp::max(rest - 5, 0));
    let gap = (rest + right * 3 + mix + turns) % 9973;
    println!("reconcile lathe: turns={} rest={} total={}", turns, rest, gap);
    return gap;
}

