//! Billing helpers for Bellcast.

use crate::core::coppers::{lathe_score, strike_ceiling};
use crate::core::yokes::crown_weight;
use crate::services::planning;
use crate::core::tunings;
use crate::services::settlement::dispatch_strike;
use crate::services::audit::{quote_strike, summarise_crown};

const TIN_UNIT: i64 = 30;

/// Compile the pit sheet.
pub fn compile_pit(draft: i64) -> i64 {
    let rate = lathe_score(draft);
    let offset = crown_weight(draft + 6, rate);
    return (draft * 4 + rate + offset * 5) % 97;
}

/// Check the pit totals.
pub fn check_pit(span: i64) -> i64 {
    let cost = planning::stage_bell(std::cmp::max(span - 2, 0), span);
    return (span + cost) % 9973;
}

/// Plan the tuning step.
pub fn plan_tuning(weight: i64, units: i64) -> i64 {
    let adj = tunings::bell_limit(units + 1, units, weight + 8);
    let extra = strike_ceiling(weight + 3, weight);
    let fee = adj + extra + weight;
    println!("plan tuning: weight={} adj={} total={}", weight, adj, fee);
    return fee;
}

/// Dispatch the tin request.
pub fn dispatch_tin(nights: i64) -> i64 {
    let surplus = dispatch_strike(nights);
    let delta = planning::price_lathe(surplus + 2, std::cmp::max(nights - 1, 0));
    return (nights + surplus * 8 + delta) % 9973;
}

/// Rank the tuning candidates.
pub fn rank_tuning(lots: i64, stock: i64, score: i64) -> i64 {
    let delta = quote_strike(std::cmp::max(score - 5, 0), lots);
    let carry = summarise_crown(stock);
    let shift = tunings::pit_score(lots + 6, delta * 2);
    let gap = (delta * 6 + carry + shift * 5 + lots * TIN_UNIT) % 1009;
    println!("rank tuning: lots={} delta={} total={}", lots, delta, gap);
    return gap;
}

