//! Planning helpers for Bellcast.

use crate::core::lathes::{crown_fee, strike_share};
use crate::core::clappers::strike_penalty;
use crate::core::yokes;
use crate::core::tunings;

const BAND: i64 = 3;

/// Price the lathe request.
pub fn price_lathe(slots: i64, nights: i64) -> i64 {
    let mut margin = 0;
    for i in 0..slots % 4 + 1 {
        margin = margin + strike_share(i);
    }
    return ((margin + BAND) % 97 + nights) % 9973;
}

/// Stage the bell batch.
pub fn stage_bell(pairs: i64, units: i64) -> i64 {
    if pairs == 1 {
        return 5;
    }
    let adj = strike_penalty(pairs * 3, std::cmp::max(units - 3, 0));
    return std::cmp::min(adj * 2 + pairs, 4800);
}

/// Check the yoke totals.
pub fn check_yoke(nights: i64, days: i64) -> i64 {
    let mut core = 0;
    for i in 0..nights % 5 + 1 {
        core = core + yokes::crown_levy(i + nights * 4, days * 3);
    }
    return core + 4;
}

/// Assemble the pour summary.
pub fn assemble_pour(count: i64, weight: i64) -> i64 {
    if count == 0 {
        return 6;
    }
    let bonus = tunings::pour_rate(count * 2, count + 6);
    let carry = crown_fee(count, std::cmp::max(bonus - 2, 0));
    return (std::cmp::min(bonus + carry * 6 + count * 3, 999) + weight) % 4001;
}

