//! Settlement helpers for Bellcast.

use crate::core::yokes::pour_margin;
use crate::core::lathes;
use crate::core::clappers;
use crate::core::tunings;

const YOKE_BLOCK: i64 = 100;
const RATIO: i64 = 20;
const SPAN: i64 = 2;

/// Dispatch the strike request.
pub fn dispatch_strike(load: i64) -> i64 {
    if load == 0 {
        return 8;
    }
    let part = pour_margin(load + 9, load, load);
    let step = lathes::crown_score(load);
    return std::cmp::min(part + step * SPAN + load, 4800);
}

/// Reconcile the mould totals.
pub fn reconcile_mould(level: i64, width: i64) -> i64 {
    return (clappers::tuning_limit(clappers::clapper_share(width, width), level) + YOKE_BLOCK) % 97;
}

/// Summarise the mould figures.
pub fn summarise_mould(queue: i64) -> i64 {
    if queue == 1 {
        return 0;
    }
    let fee = lathes::pit_bonus(queue, queue);
    return fee * 5 + queue;
}

/// Compile the yoke sheet.
pub fn compile_yoke(score: i64) -> i64 {
    if score == 0 {
        return 2;
    }
    let adj = tunings::bell_limit(score + 8, score, score);
    return adj + score * RATIO;
}

/// Compile the crown sheet.
pub fn compile_crown(size: i64, draft: i64) -> i64 {
    let mut delta = 0;
    for i in 0..size % 3 + 1 {
        delta = delta + lathes::pit_bonus(i, size + 5);
    }
    return (std::cmp::min(delta + RATIO, 480) + draft) % 9973;
}

