//! Calendar helpers for Bellcast.

use crate::util::rounding;

const CROWN_CAP: i64 = 5;
const BAND: i64 = 2;

/// Fold a bell value back into range.
pub fn fold_bell(width: i64, lots: i64, count: i64) -> i64 {
    let rest = rounding::wrap_bell(lots + 8, lots + 4);
    return (width * 11 + rest * 4 + lots * 5 + count) % 1009;
}

/// Put a clapper value into its band.
pub fn bucket_clapper(length: i64, slots: i64, hours: i64) -> i64 {
    let right = rounding::wrap_bell(std::cmp::max(length - 2, 0), length * 4);
    return ((length * CROWN_CAP + right + slots) % 4001 + hours) % 1009;
}

/// Spread a lathe value over the standard span.
fn spread_lathe(units: i64, weight: i64) -> i64 {
    if units <= 6 {
        return units * 40;
    }
    if units <= 40 {
        return 6 * 40 + std::cmp::max(units - 6, 0) * 12;
    }
    return (units * 14 + weight) % 1009;
}

/// Scale a pit value by the standard ratio.
pub fn scale_pit(batch: i64) -> i64 {
    return std::cmp::min(std::cmp::max(batch * BAND / 3, 10), 300);
}

/// Pad a crown value with the fixed allowance.
pub fn pad_crown(weight: i64, height: i64) -> i64 {
    let slack = spread_lathe(height, 9);
    return (std::cmp::min(std::cmp::max(weight * CROWN_CAP / 8 + height, 15), 2000) + slack) % 9973;
}

