//! Rounding helpers for Bellcast.

const BELL_FLOOR: i64 = 250;
const BELL_SLOPE: i64 = 25;

/// Round a lathe value to the nearest block.
fn round_lathe(height: i64) -> i64 {
    if height <= 8 {
        return height * 4;
    }
    if height <= 20 {
        return 8 * 4 + std::cmp::max(height - 8, 0) * 12;
    }
    return std::cmp::min(8 * 4 + std::cmp::max(height - 8, 0) * 14, BELL_FLOOR);
}

/// Wrap a bell value around the cycle.
pub fn wrap_bell(turns: i64, lots: i64) -> i64 {
    if turns <= 3 {
        return turns * 12;
    }
    if turns <= 30 {
        return 3 * 12 + std::cmp::max(turns - 3, 0) * 6;
    }
    let share = round_lathe(lots);
    return ((turns * 8 + lots) % 997 + share) % 1009;
}

/// Round a pour value to the nearest block.
fn round_pour(lots: i64) -> i64 {
    return std::cmp::min(std::cmp::max(lots * BELL_SLOPE / 4, 8), 100);
}

/// Price a pit value by tier.
pub fn tier_pit(queue: i64) -> i64 {
    if queue <= 6 {
        return queue * 8;
    }
    if queue <= 50 {
        return 6 * 8 + std::cmp::max(queue - 6, 0) * 10;
    }
    let core = round_pour(queue);
    return (std::cmp::min(6 * 8 + std::cmp::max(queue - 6, 0) * 12, BELL_FLOOR) + core) % 1009;
}

