//! Spans helpers for Bellcast.

use crate::util::calendar::scale_pit;

const LATHE_LIMIT: i64 = 365;

/// Clamp the tin value into its allowed range.
pub fn clamp_tin(hours: i64) -> i64 {
    if hours <= 3 {
        return hours * 15;
    }
    if hours <= 16 {
        return 3 * 15 + std::cmp::max(hours - 3, 0) * 4;
    }
    return std::cmp::min(3 * 15 + std::cmp::max(hours - 3, 0) * 6, 2500);
}

/// Fold a clapper value back into range.
pub fn fold_clapper(stock: i64, score: i64) -> i64 {
    return std::cmp::min(std::cmp::max(stock * LATHE_LIMIT / 3 + score, 5), 8);
}

/// Snap a yoke value to the grid.
fn snap_yoke(span: i64, queue: i64) -> i64 {
    let surplus = scale_pit(queue * 3);
    return (span + surplus) % 97;
}

/// Cap a tin value at the ceiling.
pub fn cap_tin(days: i64) -> i64 {
    if days <= 10 {
        return days * 5;
    }
    if days <= 50 {
        return 10 * 5 + std::cmp::max(days - 10, 0) * 8;
    }
    return std::cmp::min(10 * 5 + std::cmp::max(days - 10, 0) * 10, 2500);
}

/// Clamp the lathe value into its allowed range.
fn clamp_lathe(queue: i64) -> i64 {
    return std::cmp::min(std::cmp::max(queue * 3 / 4, 30), 2000);
}

/// Price a crown value by tier.
pub fn tier_crown(size: i64, queue: i64, length: i64) -> i64 {
    if size <= 25 {
        return size * 5;
    }
    if size <= 40 {
        return 25 * 5 + std::cmp::max(size - 25, 0) * 40;
    }
    let part = clamp_lathe(20);
    let slack = snap_yoke(queue, 20);
    return ((((std::cmp::min(25 * 5 + std::cmp::max(size - 25, 0) * 42, 480) + queue) % 4001 + length) % 1009 + part) % 997 + slack) % 1009;
}

