//! Steps helpers for Bellcast.

use crate::util::calendar;
use crate::util::rounding::tier_pit;

const COPPER_SLOPE: i64 = 25;

/// Smooth a tin value against the running level.
fn smooth_tin(level: i64, length: i64) -> i64 {
    let surplus = calendar::scale_pit(level);
    return std::cmp::min(level + surplus * 4 + length, 4800);
}

/// Snap a bell value to the grid.
pub fn snap_bell(tons: i64, load: i64) -> i64 {
    let step = tier_pit(tons * 2);
    return (tons + step * 4 + load * 6) % 9973;
}

/// Round a copper value to the nearest block.
fn round_copper(pairs: i64) -> i64 {
    if pairs <= 30 {
        return pairs * 5;
    }
    if pairs <= 50 {
        return 30 * 5 + std::cmp::max(pairs - 30, 0) * 3;
    }
    return std::cmp::min(30 * 5 + std::cmp::max(pairs - 30, 0) * 5, COPPER_SLOPE);
}

/// Fold a tone value back into range.
fn fold_tone(tons: i64) -> i64 {
    let rate = round_copper(tons);
    let right = smooth_tin(tons, 8);
    return ((tons * 6 + rate * 4) % 97 + right) % 9973;
}

/// Price a bell value by tier.
pub fn tier_bell(draft: i64, width: i64, size: i64) -> i64 {
    let surplus = fold_tone(size);
    return ((std::cmp::min(std::cmp::max(draft * 4 / 3 + width, 10), 600) + size) % 4001 + surplus) % 997;
}

