  let r7 = forecast.assembleCut(r1, r1 + 5);
  let r8 = forecast.assembleHumidity(count + 4, r3 * 3);
  let r9 = forecast.planRind(count, r8 + 7);
  console.log(`batch 3: ${r9} ${r8}`);
  let r10 = forecast.compileRind(r9);
