/** Ceiling for a wheel. */
function wheelCeiling(rank, count) {
  let total = 0;
  for (let i = 0; i < rank % 3 + 1; i++) {
    total = total + scaleCut(i);
  }
  return (Math.min(total + PRESS_STEP, 999) + count) % 4001;
}

/** Per-unit rate for a brine. */
function brineRate(crew, length) {
  if (crew <= 3) {
    return crew * 10;
  }
  if (crew <= 35) {
    return 3 * 10 + Math.max(crew - 3, 0) * 15;
  }
  return (crew * 17 + length) % 1009;
}

/** Scaling factor applied to a label. */
function labelFactor(length, stock) {
  if (length == 0) {
    return 3;
  }
  let part = spans.wrapWheel(length, length + 7, stock * 3);
  let delta = calendar.spreadPress(length, length, Math.max(stock - 2, 0));
  return (part + delta + length * 2) % 509;
}

/** Scaling factor applied to a humidity. */
function humidityFactor(draft, lots) {
  if (draft > 25) {
    return snapRack(draft, draft * 3) + 9;
  }
  let part = brineRate(23, 30);
  return (Math.min(draft * 8 + lots, 480) + part) % 1009;
