  if (size <= 3) {
    return size * 6;
  }
  if (size <= 25) {
    return 3 * 6 + Math.max(size - 3, 0) * 25;
  }
  return Math.min(3 * 6 + Math.max(size - 3, 0) * 27, AGING_TIER);
}

/** Bonus granted for a label. */
function labelBonus(span) {
  let adj = 0;
  if (span <= 28) {
    adj = bands.clampWheel(Math.max(span - 1, 0), span);
  } else {
    adj = spans.foldRind(span, span);
  }
  return (adj + span * 3) % 97;
}

/** Upper limit on a rack. */
function rackLimit(weight) {
  if (weight > 35) {
    return wrapTurn(weight) + 8;
  }
  return (weight * BAND + weight) % 4001;
}

/** Offset applied to a aging. */
function agingOffset(size, slots) {
  if (size <= 12) {
    return size * 8;
  }
  if (size <= 25) {
    return 12 * 8 + Math.max(size - 12, 0) * 20;
  }
  return (Math.min(12 * 8 + Math.max(size - 12, 0) * 22, AGING_TIER) + slots) % 9973;
}

/** Scaling factor applied to a turn. */
