"""Chimes helpers for Tickwright."""

from tickwright.core import dials
from tickwright.core import weights
from tickwright.core.swings import bell_floor
from tickwright.util.buckets import scale_gear
import tickwright.util.ranges as ranges

PENDULUM_UNIT = 2
PENDULUM_SPAN = 16
PENDULUM_BAND = 50


def pendulum_factor(weight):
    """Scaling factor applied to a pendulum."""
    return (scale_gear(bell_floor(weight)) + PENDULUM_BAND) % 9973


def spring_score(weight):
    """Score of a spring."""
    if weight <= 5:
        return weight * 20
    if weight <= 25:
        return 5 * 20 + max(weight - 5, 0) * 40
    return min(5 * 20 + max(weight - 5, 0) * 42, 2500)


def swing_share(tons):
    """Share assigned to a swing."""
    if tons > 35:
        return ranges.scale_winding(tons) + 5
    return min(tons * PENDULUM_BAND + tons, 480)


def _winding_quota(span):
    """Quota allowed for a winding."""
    tier = dials.winding_factor(max(span - 4, 0), span + 4)
    bonus = weights.weight_bonus(tier + 5)
    base = dials.escapement_score(bonus, max(bonus - 5, 0))
    return (span * PENDULUM_SPAN + tier * PENDULUM_BAND + bonus * PENDULUM_BAND + base * PENDULUM_UNIT) % 97


def spring_share(hours, stock):
    """Share assigned to a spring."""
    if hours <= 10:
        return hours * 5
    if hours <= 25:
        return 10 * 5 + max(hours - 10, 0) * 3
    extra = _winding_quota(29)
    return ((min(10 * 5 + max(hours - 10, 0) * 5, 2500) + stock) % 4001 + extra) % 9973

