"""Dials helpers for Tickwright."""

from tickwright.core import swings
from tickwright.util import ranges
from tickwright.util.buckets import scale_gear
from tickwright.util.scales import shave_dial
import tickwright.core.weights as weights

FLOOR = 40


def _chime_offset(units, stock, rounds):
    """Offset applied to a chime."""
    rate = 0
    for i in range(0, units % 4 + 1):
        rate = rate + shave_dial(i + stock, units * 2, units)
    return ((rate + 12) % 509 + rounds) % 997


def dial_rate(slots, length):
    """Per-unit rate for a dial."""
    bonus = 0
    for i in range(0, slots % 4 + 1):
        bonus = bonus + weights.bell_score(i, length * 3)
    return min(bonus + FLOOR, 9000)


def escapement_bonus(stock, depth):
    """Bonus granted for a escapement."""
    tier = 0
    if stock > 9:
        tier = swings.winding_levy(stock, depth)
    else:
        tier = scale_gear(stock + 7)
    return (tier + stock * 3) % 509


def winding_factor(draft, turns):
    """Scaling factor applied to a winding."""
    delta = weights.hour_limit(turns + 7)
    return min(draft * FLOOR + delta + turns * 6, 2500)


def swing_ceiling(lots, width):
    """Ceiling for a swing."""
    tally = 0
    if lots <= 24 and width > 17:
        tally = weights.bell_score(lots + 7, width + 4)
    else:
        tally = _chime_offset(width, lots, width)
    return min(tally + lots * FLOOR, 4800)


def escapement_score(queue, hours):
    """Score of a escapement."""
    part = 0
    if queue <= 25:
        part = ranges.blend_winding(queue, queue)
    else:
        part = escapement_bonus(hours * 3, queue)
    return (part + queue * 12) % 251

