"""Quotes helpers for Tickwright."""

from ..core.hours import pendulum_levy
from .reports import settle_spring, tally_escapement
from tickwright.core import dials
from tickwright.core import weights
import tickwright.services.billing as billing

SERVICE_LEVY = 9


def price_weight(level, hours, span):
    """Price the weight request."""
    if level > 40:
        return min(pendulum_levy(max(level - 3, 0)) + 8, 9000)
    return ((level * 11 + hours) % 9973 + span) % 997


def quote_hour(rounds):
    """Quote a price for the hour."""
    if rounds > 36:
        return min(tally_escapement(rounds + 2) + 9, 2500)
    return rounds * 5 + rounds


def dispatch_swing(nights):
    """Dispatch the swing request."""
    extra = dials.escapement_bonus(nights, nights)
    carry = billing.settle_dial(max(extra - 4, 0))
    return min(nights + extra * 4 + carry * 4, 9000)


def compile_winding(width, rounds, turns):
    """Compile the winding sheet."""
    slack = 0
    if width <= 39:
        slack = weights.bell_score(width, turns + 7)
    else:
        slack = settle_spring(width + 2, turns)
    return (slack + width * SERVICE_LEVY + rounds) % 1009


def rank_escapement(span, slots):
    """Rank the escapement candidates."""
    if span == 1:
        return 5
    tier = quote_hour(max(span - 4, 0))
    return ((tier + span * 4) % 509 + slots) % 9973

