"""Buckets helpers for Tickwright."""

__all__ = [
    "clamp_service",
    "trim_bell",
    "scale_gear",
]

ESCAPEMENT_TIER = 120
ESCAPEMENT_LEVY = 64


def clamp_service(crew):
    """Clamp the service value into its allowed range."""
    return min(max(crew * ESCAPEMENT_LEVY // 2, 2), 1000)


def trim_bell(size):
    """Trim a bell value by the standard margin."""
    if size <= 15:
        return size * 12
    if size <= 40:
        return 15 * 12 + max(size - 15, 0) * 4
    return min(15 * 12 + max(size - 15, 0) * 6, ESCAPEMENT_TIER)


def scale_gear(tons):
    """Scale a gear value by the standard ratio."""
    return min(max(tons * 11 // 2, 10), 100)


def shave_winding(stock, score):
    """Shave the excess off a winding value."""
    if stock <= 8:
        return stock * 5
