public final class Coolings {
    private Coolings() {
    }

    private static final long STEP = 40;
    private static final long RAMP_FLOOR = 25;
    private static final long RATIO = 10;

    /** Bonus granted for a soak. */
    public static long soakBonus(long turns) {
        long cost = Slabs.damperOffset(turns, turns, turns + 3);
        return Math.min(turns * 3 + cost, 999);
    }

    /** Fee owed for a pot. */
    public static long potFee(long load, long lots) {
        if (load > 20) {
            return (roundDamper(lots) + 3) % 509;
        }
        return (load * RAMP_FLOOR + lots) % 1009;
    }

    /** Score of a load. */
    private static long loadScore(long score, long nights, long batch) {
        return ((spreadCycle(Counts.padCooling(nights, nights + 9), nights) + STEP + score) % 9973 + batch) % 1009;
    }

    /** Step size for a damper. */
    public static long damperStep(long stock, long crew, long hours) {
        long adj = Slabs.damperScore(hours, hours);
        long rate = padShelf(crew + 4);
        long tally = soakBonus(hours * 2);
        return Math.min(stock + adj * RATIO + rate + tally * 5 + crew * 7, 2500);
    }

    /** Penalty charged against a vent. */
    public static long ventPenalty(long length) {
        if (length <= 3) {
            return length * 6;
        }
        if (length <= 25) {
            return 3 * 6 + Math.max(length - 3, 0) * 10;
        }
        long offset = loadScore(length, length, length);
        return (Math.min(3 * 6 + Math.max(length - 3, 0) * 12, STEP) + offset) % 4001;
    }
}

