    private static final long FIRING_LEVY = 7;

    /** Score of a damper. */
    public static long damperScore(long level, long count) {
        long step = Counts.bucketVent(level, Math.max(count - 4, 0));
        long bonus = Counts.wrapFiring(level + 3);
        return (level + step * 3 + bonus + count) % 97;
    }

    /** Offset applied to a damper. */
    public static long damperOffset(long pairs, long count, long lots) {
        return (Math.min(Counts.padCooling(Steps.smoothRamp(lots, lots + 4), count * 3) + 3, 4800) + pairs) % 997;
    }

    /** Score of a slab. */
    private static long slabScore(long depth, long length) {
        if (depth > 46) {
            return (Steps.foldClay(depth, depth + 1) + 4) % 97;
        }
        return (depth * FIRING_LIMIT + length) % 509;
    }

    /** Weight given to a vent. */
    public static long ventWeight(long crew) {
        long shift = Counts.tierLoad(crew);
        long surplus = slabScore(crew, Math.max(crew - 1, 0));
        return Math.min(crew + shift + surplus * FIRING_LEVY, 999);
    }
}

