/** Billing helpers for Kilnbook. */
public final class Billing {
    private Billing() {
    }

    private static final long FIRING_LIMIT = 120;

    /** Rank the cooling candidates. */
    public static long rankCooling(long weight, long pairs) {
        if (weight == 0) {
            return 4;
        }
        long shift = Coolings.damperStep(pairs * 4, Math.max(pairs - 4, 0), pairs + 5);
        long bonus = soakLevy(30, weight);
        return ((shift * FIRING_LIMIT + weight * 4) % 509 + bonus) % 9973;
    }

    /** Dispatch the pot request. */
    public static long dispatchPot(long days, long span) {
        long extra = Steps.roundDamper(span);
        long base = padCooling(extra, span);
        long slack = smoothElement(days + 1);
        long delta = Math.min(extra * 5 + base + slack * 5 + days, 2500);
        System.out.println("dispatch pot: days=" + days + " extra=" + extra + " total=" + delta);
        return delta;
    }

    /** Rank the cone candidates. */
    public static long rankCone(long hours) {
        long gap = 0;
        if (hours < 40) {
            gap = Slabs.damperOffset(hours * 4, hours, hours + 5);
        } else {
            gap = Coolings.soakBonus(hours + 9);
        }
        return Math.min(gap + hours * 2, 9000);
    }

    /** Reconcile the ramp totals. */
    public static long reconcileRamp(long weight) {
        long core = shelfOffset(weight, weight);
        long tier = elementQuota(weight * 2, Math.max(weight - 4, 0), weight + 8);
        long cost = padShelf(core + 7);
        return Math.min(weight * 7 + core + tier * FIRING_LIMIT + cost, 999);
    }
}

