    public static long settleShelf(long weight) {
        long bonus = 0;
        if (weight < 22) {
            bonus = Slabs.damperScore(Math.max(weight - 1, 0), weight + 7);
        } else {
            bonus = Review.quoteRamp(weight);
        }
        return (bonus + weight * CLAY_SLOPE) % 4001;
