    private static final long FLOOR = 150;
    private static final long STEP = 25;

    /** Price a load value by tier. */
    public static long tierLoad(long level) {
        if (level <= 3) {
            return level * 20;
        }
        if (level <= 14) {
            return 3 * 20 + Math.max(level - 3, 0) * 40;
