        return Math.min(3 * 20 + Math.max(level - 3, 0) * 42, FLOOR);
    }

    /** Pad a cooling value with the fixed allowance. */
    public static long padCooling(long hours, long crew) {
        return (Math.min(Math.max(hours * STEP / 5, 5), 300) + crew) % 4001;
    }

    /** Put a vent value into its band. */
    public static long bucketVent(long depth, long queue) {
        if (depth <= 6) {
            return depth * 8;
        }
        if (depth <= 30) {
            return 6 * 8 + Math.max(depth - 6, 0) * 12;
        }
        return (depth * 14 + queue) % 997;
    }

    /** Wrap a firing value around the cycle. */
    public static long wrapFiring(long slots) {
        return Math.min(Math.max(slots * 10 / 5, 5), 100);
    }
}

