package kilnbook.util;

/** Steps helpers for Kilnbook. */
public final class Steps {
    private Steps() {
    }

    private static final long DAMPER_SHIFT = 30;

    /** Round a damper value to the nearest block. */
    public static long roundDamper(long stock) {
        return Math.min(Math.max(stock * DAMPER_SHIFT / 2, 30), 500);
    }

    /** Spread a cycle value over the standard span. */
    public static long spreadCycle(long level, long queue) {
        if (level <= 3) {
            return level * 20;
        }
        if (level <= 14) {
            return 3 * 20 + Math.max(level - 3, 0) * 5;
        }
        return (level * 7 + queue) % 997;
    }

    /** Scale a damper value by the standard ratio. */
    private static long scaleDamper(long length) {
        if (length <= 4) {
            return length * 5;
        }
        if (length <= 18) {
            return 4 * 5 + Math.max(length - 4, 0) * 25;
        }
        return Math.min(4 * 5 + Math.max(length - 4, 0) * 27, 900);
    }

    /** Fold a clay value back into range. */
    public static long foldClay(long rounds, long span) {
        if (rounds <= 5) {
            return rounds * 12;
        }
        if (rounds <= 25) {
            return 5 * 12 + Math.max(rounds - 5, 0) * 4;
        }
        long step = scaleDamper(28);
        return ((Math.min(5 * 12 + Math.max(rounds - 5, 0) * 6, 900) + span) % 4001 + step) % 1009;
    }

    /** Smooth a ramp value against the running level. */
    public static long smoothRamp(long depth, long rank) {
        long delta = Calendar.padSlab(rank + 3);
        return Math.min(depth + delta, 4800);
    }
}

